SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

DROP TABLE IF EXISTS `poi_activities`;
CREATE TABLE `poi_activities` (
  `activity_id` int unsigned NOT NULL COMMENT 'Klook 活动 ID',
  `title` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '标题',
  `subtitle` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '副标题',
  `what_we_love` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '活动描述',
  `supported_languages` json DEFAULT NULL COMMENT '支持的语言列表',
  `available_date` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '最早可购买时间',
  `location` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '坐标，格式：纬度,经度',
  `address_desc` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '地址',
  `currency` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '货币',
  `price` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '价格',
  `has_msp` tinyint(1) DEFAULT '0' COMMENT '是否有最低售卖价格',
  `images` json DEFAULT NULL COMMENT '图片列表',
  `city_info` json DEFAULT NULL COMMENT '城市信息',
  `departure_city_info` json DEFAULT NULL COMMENT '出发城市信息',
  `category_info` json DEFAULT NULL COMMENT '类目信息',
  `section_info` json DEFAULT NULL COMMENT '活动级描述信息',
  `package_list` json DEFAULT NULL COMMENT '原始 detail JSON（含 package_list）',
  `duration` json DEFAULT NULL COMMENT '活动时长（0-2个值）',
  `spec_attr_definition` json DEFAULT NULL COMMENT '套餐可选销售属性定义',
  `city_id` int unsigned NOT NULL DEFAULT '0' COMMENT '所属城市 ID',
  `country_id` int unsigned NOT NULL DEFAULT '0' COMMENT '所属国家 ID',
  `category_id` int unsigned NOT NULL DEFAULT '0' COMMENT '主类目 ID',
  `sub_category_id` int unsigned NOT NULL DEFAULT '0' COMMENT '子类目 ID',
  `leaf_category_id` int unsigned NOT NULL DEFAULT '0' COMMENT '叶子类目 ID',
  `content_md5` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '活动级字段 MD5，用于变更检测',
  `detail_synced_at` datetime DEFAULT NULL COMMENT '详情最后同步时间，NULL 表示尚未同步',
  `status` int NOT NULL DEFAULT '1' COMMENT '1正常 3删除',
  `created_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`activity_id`),
  KEY `idx_city_id` (`city_id`),
  KEY `idx_country_id` (`country_id`),
  KEY `idx_category_id` (`category_id`),
  KEY `idx_detail_synced_at` (`detail_synced_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Klook 活动主表';

